package runtimecore

import (
	"context"
	"encoding/json"
	"path/filepath"

	"github.com/liuzq1103/mihomoctl/internal/platform"
)

type generatedConfig struct {
	Hash      string `json:"config_sha256"`
	Automatic bool   `json:"automatic_ports"`
	Retries   int    `json:"retries"`
}

func generatedPath(a platform.App) string {
	return filepath.Join(a.Scope.StateRoot, "generated-config.json")
}

// Only an unchanged configuration generated by init may have its candidate ports
// reassigned. Imported, edited and explicitly pinned ports always fail closed.
func retryManagedPorts(ctx context.Context, a platform.App, x resolved) error {
	original, e := platform.ReadPrivate(generatedPath(a))
	if e != nil {
		return platform.Fail("port-conflict")
	}
	var rec generatedConfig
	if json.Unmarshal(original, &rec) != nil || !rec.Automatic || rec.Hash != platform.Hash(x.Text) || rec.Retries >= 3 || len(x.Endpoints) != 1 || x.Endpoints[0].Name != "proxy" || x.Controller == nil {
		return platform.Fail("port-conflict")
	}
	p, e := freePort()
	if e != nil {
		return e
	}
	cp, e := freePort()
	if e != nil {
		return e
	}
	for cp == p {
		cp, e = freePort()
		if e != nil {
			return e
		}
	}
	rows, ok := x.Config["listeners"].([]any)
	if !ok || len(rows) != 1 {
		return platform.Fail("port-conflict")
	}
	platform.Map(rows[0])["port"] = p
	x.Config["external-controller"] = endpoint{Address: "127.0.0.1", Port: cp}.address()
	candidate, e := marshalYAML(x.Config)
	if e != nil {
		return e
	}
	if e = validateCore(ctx, a, x.Manager.Core.Binary, candidate); e != nil {
		return e
	}
	rec.Hash = platform.Hash(candidate)
	rec.Retries++
	receipt, e := json.Marshal(rec)
	if e != nil {
		return e
	}
	if e = applyFiles(a, map[string][]byte{x.Manager.Core.Config: candidate, generatedPath(a): receipt}); e != nil {
		return e
	}
	if e = lifecycle(ctx, a, "start"); e != nil {
		if re := applyFiles(a, map[string][]byte{x.Manager.Core.Config: x.Text, generatedPath(a): original}); re != nil {
			return platform.Fail("rollback-failed")
		}
		return e
	}
	return nil
}
